<?php require_once __DIR__.'/includes/functions.php';require_login();$role=current_user()['role'];if($_SERVER['REQUEST_METHOD']==='POST'){require_role(['admin','staff']);$act=$_POST['action']??'';if($act==='save'){$id=(int)($_POST['id']??0);$isbn=trim($_POST['isbn']??'')?:null;$title=trim($_POST['title']??'');$author=trim($_POST['author']??'');$cat=(int)($_POST['category_id']??0)?:null;$pub=trim($_POST['publisher']??'')?:null;$year=(int)($_POST['published_year']??0)?:null;$total=max(0,(int)($_POST['total_copies']??1));$desc=trim($_POST['description']??'');if($title===''||$author===''||$total<1){flash('Title, author and at least one copy are required.','error');}else{try{if($id){$s=$db->prepare('SELECT total_copies,available_copies FROM books WHERE id=?');$s->bind_param('i',$id);$s->execute();$old=$s->get_result()->fetch_assoc();$borrowed=$old['total_copies']-$old['available_copies'];if($total<$borrowed){throw new Exception('Total copies cannot be less than currently borrowed copies.');}$avail=$total-$borrowed;$s=$db->prepare('UPDATE books SET isbn=?,title=?,author=?,category_id=?,publisher=?,published_year=?,total_copies=?,available_copies=?,description=? WHERE id=?');$s->bind_param('sssisiiisi',$isbn,$title,$author,$cat,$pub,$year,$total,$avail,$desc,$id);}else{$avail=$total;$s=$db->prepare('INSERT INTO books(isbn,title,author,category_id,publisher,published_year,total_copies,available_copies,description) VALUES(?,?,?,?,?,?,?,?,?)');$s->bind_param('sssisiiis',$isbn,$title,$author,$cat,$pub,$year,$total,$avail,$desc);} $s->execute();log_action($id?'book_updated':'book_created','books',$id?:$db->insert_id,$title);flash('Book saved.');}catch(Throwable $e){flash($e instanceof mysqli_sql_exception?'Could not save book. Check for duplicate ISBN and valid fields.':$e->getMessage(),'error');}}header('Location: '.url('books.php'));exit;}if($act==='delete'){ $id=(int)$_POST['id'];$s=$db->prepare("SELECT COUNT(*) n FROM transactions WHERE book_id=? AND status IN ('pending','approved','released')");$s->bind_param('i',$id);$s->execute();if($s->get_result()->fetch_assoc()['n'])flash('Cannot delete a book with active transactions.','error');else{$s=$db->prepare('UPDATE books SET is_archived=1 WHERE id=?');$s->bind_param('i',$id);$s->execute();log_action('book_archived','books',$id);flash('Book archived. Transaction history has been retained.');}header('Location: '.url('books.php'));exit;}}
$q=trim($_GET['q']??'');$cat=(int)($_GET['category']??0);$where=' WHERE b.is_archived=0';$types='';$vals=[];if($q!==''){$where.=' AND (b.title LIKE ? OR b.author LIKE ? OR b.isbn LIKE ?)';$like="%$q%";$types.='sss';array_push($vals,$like,$like,$like);}if($cat){$where.=' AND b.category_id=?';$types.='i';$vals[]=$cat;}$sql='SELECT b.*,c.name category FROM books b LEFT JOIN categories c ON c.id=b.category_id'.$where.' ORDER BY b.title';$s=$db->prepare($sql);if($types)$s->bind_param($types,...$vals);$s->execute();$books=$s->get_result();$cats=$db->query('SELECT id,name FROM categories ORDER BY name');$title='Books';require 'includes/header.php';?>
<h1>Books catalogue</h1><div class="panel"><form class="filters" method="get"><div><label>Search title, author, ISBN</label><input name="q" value="<?=e($q)?>" placeholder="Search books"></div><div><label>Category</label><select name="category"><option value="0">All categories</option><?php while($c=$cats->fetch_assoc()):?><option value="<?=$c['id']?>" <?=$cat===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endwhile;?></select></div><button>Search</button></form></div>
<?php if(in_array($role,['admin','staff'])):?><div class="panel"><h2>Add / edit book</h2><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="0"><div class="grid"><div><label>Title *</label><input name="title" required></div><div><label>Author *</label><input name="author" required></div><div><label>ISBN</label><input name="isbn"></div><div><label>Category</label><select name="category_id"><option value="0">Uncategorized</option><?php $cc=$db->query('SELECT id,name FROM categories ORDER BY name');while($c=$cc->fetch_assoc()):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endwhile;?></select></div><div><label>Publisher</label><input name="publisher"></div><div><label>Year</label><input type="number" name="published_year" min="1000" max="2100"></div><div><label>Total copies</label><input type="number" name="total_copies" value="1" min="1" required></div></div><label>Description</label><textarea name="description" rows="2"></textarea><button>Save new book</button></form><p class="muted">To edit, use the edit form from the table row. Staff and administrators can manage catalogue records.</p></div><?php endif;?>
<div class="panel table-wrap"><table><thead><tr><th>Book</th><th>Category</th><th>Inventory</th><th>Action</th></tr></thead><tbody><?php while($b=$books->fetch_assoc()):?><tr><td><b><?=e($b['title'])?></b><br><span class="muted"><?=e($b['author'])?> · ISBN <?=e($b['isbn']??'—')?></span><br><?=e($b['description']??'')?></td><td><?=e($b['category']??'Uncategorized')?></td><td><?=e($b['available_copies'])?> available / <?=e($b['total_copies'])?> total</td><td><?php if($role==='user'):?><form method="post" action="transactions.php"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="request"><input type="hidden" name="book_id" value="<?=$b['id']?>"><select name="type"><option value="borrow">Borrow</option><option value="reservation">Reserve</option></select><button>Request</button></form><?php elseif(in_array($role,['admin','staff'])):?><details><summary>Edit</summary><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$b['id']?>"><label>Title</label><input name="title" value="<?=e($b['title'])?>" required><label>Author</label><input name="author" value="<?=e($b['author'])?>" required><label>ISBN</label><input name="isbn" value="<?=e($b['isbn'])?>"><label>Category</label><select name="category_id"><option value="0">Uncategorized</option><?php $ec=$db->query('SELECT id,name FROM categories ORDER BY name');while($ecat=$ec->fetch_assoc()):?><option value="<?=$ecat['id']?>" <?=$b['category_id']==$ecat['id']?'selected':''?>><?=e($ecat['name'])?></option><?php endwhile;?></select><label>Publisher</label><input name="publisher" value="<?=e($b['publisher'])?>"><label>Year</label><input type="number" name="published_year" min="1000" max="2100" value="<?=e($b['published_year'])?>"><label>Total copies</label><input type="number" name="total_copies" min="1" value="<?=$b['total_copies']?>"><label>Description</label><textarea name="description"><?=e($b['description'])?></textarea><button>Update</button></form><form method="post" data-confirm="Delete this book?"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$b['id']?>"><button class="btn danger">Delete</button></form></details><?php else:?>View only<?php endif;?></td></tr><?php endwhile;?></tbody></table></div><?php require 'includes/footer.php';?>
